mapper.select:
/* 후보정심사단어사전 자동 등록 - 완료건(승인 및 Block) 조회 */
/* WordDictionaryRegBatchMapper.selectTargetList */
SELECT INPT_MST_SRNO AS INPT_MST_SRNO FROM CSPD001TM
WHERE AI_INPT_ACVT_CD IN ('160')
  AND INPT_RCP_DT = #{inptRcpDt}

/* 후보정심사단어사전 자동 등록 - 이미 등록된 수기단어인지 개수 조회  */
/* WordDictionaryRegBatchMapper.selectCountAleadyReg */
SELECT  COUNT(*) AS cnt
FROM    CSPD117TI --AI심사용어사전정보
WHERE   AI_INPT_GRP_CD = #{aiInptIntfItmNm}  --AI심사그룹코드
AND     AI_INPT_WORD_TXT = #{itmInptHndgInpDatTxt} --AI심사단어내용
